        "transcript": "Interviewer: Welcome, Musa! Our intermediate students want to know about your lifestyle.\nMusa: Thank you! I grew up in a very humble neighborhood. Football gave me purpose. I train twice a day, every day except Fridays. Because of my rigorous training schedule, I spend less time with my family than I would like, but they always support me. I am immensely proud to wear the green jersey and represent my country in international tournaments. I don't care much for fancy designer clothes; I prefer simple athletic wear. Most importantly, I give a portion of my earnings every month to help charitable organizations and young orphan athletes. Sometimes the media and cameras follow me around town, which can feel overwhelming, but I understand it's part of professional sport.",
